def info(category: str) -> dict:
    """Return use/name/note for a stored category path ('virtenes/xyz' or 'flizes/gridai')."""
    first = (category or "").split("/")[0]
    use, name, note = T.get(first, ("", "", ""))
    return {"use": use, "kind_ru": name, "note": note}


def slugs_for_use(use: str) -> list[str]:
    """use: 'out' means outdoor-capable (out + both), 'in' means indoor-capable (in + both)."""
    ok = {"out": ("out", "both"), "in": ("in", "both")}.get(use, ())
    return [k for k, v in T.items() if v[0] in ok]
